package cn.mop.api;
import cn.mop.domain.operations.ExplicitOperationalMetrics;
import cn.mop.domain.operations.ExplicitOperationalMetrics.*;
import org.junit.jupiter.api.Test;
import java.math.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class ExplicitOperationalMetricsTest {
    static BigInteger i(long value){return BigInteger.valueOf(value);}
    static BigDecimal d(String value){return new BigDecimal(value);}
    @Test void oddMedianMatchesManualSortWithoutMutatingOriginal(){var values=new ArrayList<>(List.of(i(9000),i(1000),i(3000)));var before=List.copyOf(values);var result=ExplicitOperationalMetrics.medianElapsedMillis(values);assertEquals(d("3000"),result.sampleMedianMillis());assertEquals(3,result.sampleCount());assertEquals(before,values);assertEquals(Status.CALCULATED,result.status());}
    @Test void evenMedianPreservesHalfMillisecondExactly(){var result=ExplicitOperationalMetrics.medianElapsedMillis(List.of(i(9),i(2),i(1),i(3)));assertEquals(d("2.5"),result.sampleMedianMillis());assertEquals("milliseconds",result.unit());}
    @Test void explicitZeroAndDuplicatesRemainRealSamples(){var result=ExplicitOperationalMetrics.medianElapsedMillis(List.of(i(0),i(0),i(0),i(10)));assertEquals(0,result.sampleMedianMillis().signum());assertEquals(4,result.sampleCount());assertEquals(0,result.unknownCount());}
    @Test void missingCollectionEmptyCollectionAndUnknownEntryAreDistinct(){var unavailable=ExplicitOperationalMetrics.medianElapsedMillis(null);assertEquals(Reason.INPUT_UNAVAILABLE,unavailable.reason());assertNull(unavailable.sampleCount());var empty=ExplicitOperationalMetrics.medianElapsedMillis(List.of());assertEquals(Reason.EMPTY_SAMPLE,empty.reason());assertEquals(0,empty.sampleCount());assertNull(empty.sampleMedianMillis());var unknown=ExplicitOperationalMetrics.medianElapsedMillis(Arrays.asList(i(1),null,i(3)));assertEquals(Reason.UNKNOWN_SAMPLE,unknown.reason());assertEquals(3,unknown.sampleCount());assertEquals(1,unknown.unknownCount());assertNull(unknown.sampleMedianMillis());}
    @Test void medianDoesNotOverflowFixedIntegerAndRejectsUnsafeBounds(){var big=new BigInteger("9".repeat(40));assertEquals(new BigDecimal(big),ExplicitOperationalMetrics.medianElapsedMillis(List.of(big,big)).sampleMedianMillis());for(var value:List.of(i(-1),new BigInteger("1".repeat(41))))assertThrows(IllegalArgumentException.class,()->ExplicitOperationalMetrics.medianElapsedMillis(Arrays.asList(null,value)));assertThrows(IllegalArgumentException.class,()->ExplicitOperationalMetrics.medianElapsedMillis(Collections.nCopies(10001,i(1))));assertEquals(10000,ExplicitOperationalMetrics.medianElapsedMillis(Collections.nCopies(10000,i(1))).sampleCount());}
    @Test void suppliedMedianNeverBecomesVerifiedProcessingDurationOrMttr(){var result=ExplicitOperationalMetrics.medianElapsedMillis(List.of(i(3600000)));assertEquals("EXPLICIT_INPUT_NOT_PROJECT_METRICS",result.source());assertEquals("UNVERIFIED_Q27",result.durationBasisVerification());assertEquals("UNVERIFIED",result.populationVerification());assertNull(result.effectiveProcessingDuration());}
    @Test void staffingUsesBothExplicitMonthlyEquivalentsAndMatchesHandCalculation(){var r=ExplicitOperationalMetrics.tenantsPerFte(new StaffingInput(i(30),d("1.5"),d("1.0")));assertEquals(d("2.5"),r.explicitTotalFte());assertEquals(0,r.sampleTenantsPerFte().compareTo(d("12")));assertEquals(Status.CALCULATED,r.status());assertTrue(r.missingInputs().isEmpty());}
    @Test void zeroTenantsAreKnownButZeroFteIsUndefinedNotZeroOrInfinity(){var zero=ExplicitOperationalMetrics.tenantsPerFte(new StaffingInput(i(0),d("1"),d("0")));assertEquals(0,zero.sampleTenantsPerFte().signum());for(var tenants:List.of(i(0),i(10))){var r=ExplicitOperationalMetrics.tenantsPerFte(new StaffingInput(tenants,d("0"),d("0.0")));assertEquals(Reason.ZERO_FTE,r.reason());assertEquals(Status.UNDEFINED,r.status());assertNull(r.sampleTenantsPerFte());}}
    @Test void missingStaffingInputsNeverDefaultToZeroEvenWithZeroTenants(){var missing=ExplicitOperationalMetrics.tenantsPerFte(new StaffingInput(i(0),d("0"),null));assertEquals(List.of("second_line_fte"),missing.missingInputs());assertNull(missing.explicitTotalFte());assertNull(missing.sampleTenantsPerFte());assertEquals(List.of("active_tenants","on_call_fte","second_line_fte"),ExplicitOperationalMetrics.tenantsPerFte(new StaffingInput(null,null,null)).missingInputs());var noTenants=ExplicitOperationalMetrics.tenantsPerFte(new StaffingInput(null,d("1"),d("1")));assertEquals(d("2"),noTenants.explicitTotalFte());assertNull(noTenants.sampleTenantsPerFte());assertEquals(List.of("input"),ExplicitOperationalMetrics.tenantsPerFte(null).missingInputs());}
    @Test void staffingRoundsOnlyFinalDivisionToDecimal128(){var r=ExplicitOperationalMetrics.tenantsPerFte(new StaffingInput(i(1),d("1.1"),d("1.9")));assertEquals(d("0.3333333333333333333333333333333333"),r.sampleTenantsPerFte());var big=new BigInteger("9007199254740993");assertEquals(new BigDecimal(big),ExplicitOperationalMetrics.tenantsPerFte(new StaffingInput(big,d("1"),d("0"))).sampleTenantsPerFte());}
    @Test void invalidSignsAndOversizedFteDoNotHideBehindUnknownFields(){for(var value:List.of(d("-1"),d("1".repeat(41)),d("0."+"1".repeat(41))))assertThrows(IllegalArgumentException.class,()->ExplicitOperationalMetrics.tenantsPerFte(new StaffingInput(null,value,null)));assertThrows(IllegalArgumentException.class,()->ExplicitOperationalMetrics.tenantsPerFte(new StaffingInput(i(-1),null,null)));}
    @Test void explicitRatioDoesNotSelectActiveTenantDefinitionApprovalThresholdOrBilling(){var r=ExplicitOperationalMetrics.tenantsPerFte(new StaffingInput(i(30),d("1"),d("1")));assertEquals("UNVERIFIED_Q30",r.populationVerification());assertEquals("UNVERIFIED_Q23",r.staffingBasisVerification());assertNull(r.effectiveTenantsPerFte());assertNull(r.targetMet());assertFalse(r.billingApplicable());assertThrows(UnsupportedOperationException.class,()->r.missingInputs().add("invented"));}
    @Test void contradictoryMedianResultsCannotBeConstructed(){assertThrows(IllegalArgumentException.class,()->new MedianResult(Status.CALCULATED,Reason.ALL_EXPLICIT,0,0,d("0")));assertThrows(IllegalArgumentException.class,()->new MedianResult(Status.UNDEFINED,Reason.EMPTY_SAMPLE,0,0,d("0")));assertThrows(IllegalArgumentException.class,()->new MedianResult(Status.UNRESOLVED,Reason.UNKNOWN_SAMPLE,2,0,null));assertThrows(IllegalArgumentException.class,()->new MedianResult(Status.CALCULATED,Reason.ALL_EXPLICIT,2,0,d("0.25")));}
    @Test void contradictoryStaffingResultsCannotBeConstructedButExactLargeSumIsAllowed(){assertThrows(IllegalArgumentException.class,()->new StaffingResult(Status.CALCULATED,Reason.ALL_EXPLICIT,null,d("1"),List.of()));assertThrows(IllegalArgumentException.class,()->new StaffingResult(Status.UNDEFINED,Reason.ZERO_FTE,d("0"),d("0"),List.of()));assertThrows(IllegalArgumentException.class,()->new StaffingResult(Status.UNRESOLVED,Reason.MISSING_INPUT,d("1"),null,List.of("on_call_fte")));var huge=d("9".repeat(40));var result=ExplicitOperationalMetrics.tenantsPerFte(new StaffingInput(i(1),huge,huge));assertEquals(huge.add(huge),result.explicitTotalFte());assertEquals(Status.CALCULATED,result.status());}

}
